def run(_context):
    import adsk.core, adsk.fusion, adsk.cam
    app = adsk.core.Application.get()
    mgr = adsk.cam.CAMManager.get()
    lib = mgr.libraryManager
    tl = lib.toolLibraries
    def find(url, name, depth=0, results=None):
        for c in tl.childAssetURLs(url):
            s=c.toString()
            if name.lower() in s.lower():
                results.append(c)
            find(c,name,depth+1,results)
    for loc in [adsk.cam.LibraryLocations.LocalLibraryLocation, adsk.cam.LibraryLocations.CloudLibraryLocation]:
        root=tl.urlByLocation(loc)
        res=[]
        try:
            find(root,'TIW',0,res)
        except Exception as e:
            print("loc",loc,"err",e)
        for r in res:
            print(loc, r.toString())
    return None

